from __future__ import annotations

import hashlib
import struct
import unittest

from tests.synthetic_locmap import RECORDS, build_sample, raw_zstd_frame


EXPECTED_SHA256 = "74727d2426308ce1cbe3bf45041add58a7a9280688ac0e749a8aa9f18a91cd34"


def decode_fixture_frame(frame: bytes) -> bytes:
    """Inspect only the raw-frame subset generated by this synthetic fixture."""
    if frame[:4] != b"\x28\xb5\x2f\xfd":
        raise ValueError("bad synthetic zstd magic")
    descriptor = frame[4]
    if descriptor == 0x20:
        size, cursor = frame[5], 6
    elif descriptor == 0x60:
        size, cursor = struct.unpack_from("<H", frame, 5)[0] + 256, 7
    else:
        raise ValueError("unexpected synthetic zstd descriptor")
    header = int.from_bytes(frame[cursor : cursor + 3], "little")
    if header & 7 != 1 or header >> 3 != size:
        raise ValueError("unexpected synthetic zstd block")
    result = frame[cursor + 3 :]
    if len(result) != size:
        raise ValueError("bad synthetic zstd size")
    return result


class SyntheticLocaleMapTests(unittest.TestCase):
    def test_fixture_is_deterministic_and_pinned(self):
        sample = build_sample()
        self.assertEqual(sample, build_sample())
        self.assertEqual(len(sample), 404)
        self.assertEqual(hashlib.sha256(sample).hexdigest(), EXPECTED_SHA256)

    def test_raw_frame_size_boundaries(self):
        for size in (0, 1, 255, 256, 65791):
            with self.subTest(size=size):
                data = b"x" * size
                self.assertEqual(decode_fixture_frame(raw_zstd_frame(data)), data)
        with self.assertRaises(ValueError):
            raw_zstd_frame(b"x" * 65792)

    def test_fixture_blocks_and_relative_value_offsets(self):
        sample = build_sample()
        magic, version, count, reserved, first_end, second_end = struct.unpack_from(
            "<IIIIII", sample
        )
        self.assertEqual((magic, version, count, reserved), (0xDEADBEEF, 1, 2, 0))
        table_end = 24
        self.assertEqual(table_end + second_end, len(sample))
        raw_blocks = []
        for start, end in ((0, first_end), (first_end, second_end)):
            block = sample[table_end + start : table_end + end]
            codec, compressed_size, uncompressed_size = struct.unpack_from("<BII", block)
            frame = block[9:]
            self.assertEqual(codec, 4)
            self.assertEqual(len(frame), compressed_size)
            raw = decode_fixture_frame(frame)
            self.assertEqual(len(raw), uncompressed_size)
            raw_blocks.append(raw)
        self.assertEqual(struct.unpack("<QQI", raw_blocks[0]), (2, 1, 1))
        shard = raw_blocks[1]
        capacity, size, seed = struct.unpack_from("<QQQ", shard)
        self.assertEqual((capacity, size, seed), (15, 2, 0x1234))
        self.assertEqual(shard[24 + capacity], 0xFF)
        slots_start = (24 + capacity + 1 + 15 + 7) // 8 * 8
        for slot, expected_hash, expected_value in RECORDS:
            offset = slots_start + slot * 16
            key, relative, length = struct.unpack_from("<QII", shard, offset)
            value_start = offset + 8 + relative
            self.assertEqual(key, expected_hash)
            self.assertEqual(shard[value_start : value_start + length], expected_value)


if __name__ == "__main__":
    unittest.main()
